import bpy, os, json
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')

def vis(o):
    return not (o.hide_viewport or o.hide_get() or o.hide_render)

def info(o):
    return {
      'name':o.name,
      'type':o.type,
      'visible':vis(o),
      'loc':[round(float(v),3) for v in o.matrix_world.translation],
      'dims':[round(float(v),3) for v in o.dimensions],
      'collections':[c.name for c in o.users_collection]
    }

cols=[]
for c in bpy.data.collections:
    cols.append({
      'name':c.name,
      'hide_viewport':bool(c.hide_viewport),
      'hide_render':bool(c.hide_render),
      'objects':len(c.objects),
      'children':[x.name for x in c.children]
    })

focus_names=['01 WORLD | ELEVADOR LACERDA | blockout v4','00 WORLD | TERRENO MASTER','03 TERRENO | aproximacao volumetrica pendente de levantamento','12 CHATGPT | blockout jogavel v3','13 CHATGPT | terreno jogavel v1']
focus={}
for name in focus_names:
    c=bpy.data.collections.get(name)
    if c: focus[name]=[info(o) for o in c.objects]

keys=('elevador','lacerda','torre','terreno','estacao','estação','rua','road','praça','praca','prefeitura','mercado','palacio','palácio','building','edificio','edifício')
visible=[info(o) for o in bpy.context.scene.objects if vis(o) and any(k in o.name.lower() for k in keys)]
terrain_visible=[info(o) for o in bpy.context.scene.objects if vis(o) and o.type=='MESH' and ('terreno' in o.name.lower() or 'terrain' in o.name.lower())]
report={'collections':cols,'focus':focus,'visible_key_objects':visible[:180],'visible_terrains':terrain_visible}
print('FOUNDATION_ACTIVE_AUDIT_BEGIN')
print(json.dumps(report,ensure_ascii=False,separators=(',',':')))
print('FOUNDATION_ACTIVE_AUDIT_END')
